import { IUser } from 'src/services/users.service';

import { InputTypes } from '@ui-kit/Input';

import {
  IInterview,
  IQuestionBase,
  IQuestionDir,
  IQuestionInput,
  IQuestionSelect,
  IQuestionType,
  IQuestionTypeObject,
} from '../@types/interview.types';

const getEmptyBaseQuestion = (order_index = 1, typeObject: IQuestionTypeObject): IQuestionBase => {
  return {
    id: 0,
    name: '',
    text: '',
    type: IQuestionType.Input,
    typeObject,

    isCustom: false,
    isRequire: false,
    isMulti: false,
    isPrivate: false,

    order_index,
  };
};

export const getEmptyQuestionInput = (
  order_index = 1,
  typeObject: IQuestionTypeObject,
): IQuestionInput => {
  return {
    ...getEmptyBaseQuestion(order_index, typeObject),
    typeObject,
    type: IQuestionType.Input,
    params: {
      id: 0,
      type: InputTypes.text,
      pattern: '',
      placeholder: '',
      min: '',
      max: '',
      step: '',
    },
  };
};

export const getEmptyQuestionDir = (
  order_index = 1,
  typeObject: IQuestionTypeObject,
): IQuestionDir => {
  return {
    ...getEmptyBaseQuestion(order_index, typeObject),
    type: IQuestionType.Dir,
    dir: {
      id: 0,
      id_dir: 0,
      name: '',
      desc: '',
      table: '',
      field: '',
      value: '',
      isEqual: false,
    },
  };
};

export const getEmptyQuestionSelect = (
  order_index = 1,
  typeObject: IQuestionTypeObject,
): IQuestionSelect => {
  return {
    ...getEmptyBaseQuestion(order_index, typeObject),
    type: IQuestionType.Select,
    options: [],
  };
};

export const getEmptyInterview = (author: IUser): IInterview => {
  return {
    id: 0,
    name: '',
    description: '',

    date_start: new Date(),
    date_finish: new Date(Date.now() + 86400000 * 7),

    hello_text: '',
    by_text: '',

    members_limit: 0,

    isMain: false,

    hiking: null,
    author,
  };
};
